#include<iostream>
#include<cstring>
using namespace std;
class stud{
 char name[20]; int eng,cpp;
public:
 stud(char*n,int e,int c){ strcpy(name,n); eng=e; cpp=c; }
 void get(char*p,int &a,int &b){ strcpy(p,name); a=eng; b=cpp; }
 void put(char*p,int a,int b){ strcpy(name,p); eng=a; cpp=b; }
 double avg(){ return (eng+cpp)/2.0; }
 void show(){ cout<<name<<' '<<eng<<' '<<cpp<<' '<<avg()<<endl; }
};
int main(){
 char p[20]; int a,b;
 stud st1("LiLei",70,95);
 st1.get(p,a,b);
 st1.put(p,a,b);
 cout<<"st1的数据为：";
 st1.show();
 return 0;
}
